//! `validity` — known-edge method coverage for the standout framework.
//!
//! The construction contract in SPEC.md is what this binary exists to
//! exercise, so the wiring in `main` is deliberate:
//!
//! * `early` is registered *before* the application templates are loaded and
//!   `late` *after* them, so both registration orders run through `build()`.
//! * `show` resolves its argument as a standout template registry name — the
//!   `show` template includes the requested name, so a name that is not
//!   registered fails in the render pass instead of being matched on here.
//! * The application theme defines only `.ok`; the help vocabulary is left to
//!   standout's default help theme, which an application theme overlays.

use clap::{Arg, Command};
use serde::Serialize;
use standout::cli::{App, CommandContext, Output};
use standout::{embed_styles, embed_templates, handler};

/// View data for `show`: the template registry name the invocation asked for.
#[derive(Serialize)]
pub struct ShowView {
    pub name: String,
}

/// View data for the commands that render the `ok` template directly. The
/// template reads nothing, so there is nothing to carry.
#[derive(Serialize)]
pub struct OkView {}

pub mod handlers {
    use super::*;

    /// `show <name>` hands the requested registry name to the `show`
    /// template, which renders through it.
    #[handler]
    pub fn show(
        #[arg] name: String,
        #[ctx] _ctx: &CommandContext,
    ) -> Result<Output<ShowView>, anyhow::Error> {
        Ok(Output::Render(ShowView { name }))
    }

    /// Registered before application templates are loaded.
    #[handler]
    pub fn early(#[ctx] _ctx: &CommandContext) -> Result<Output<OkView>, anyhow::Error> {
        Ok(Output::Render(OkView {}))
    }

    /// Registered after application templates are loaded.
    #[handler]
    pub fn late(#[ctx] _ctx: &CommandContext) -> Result<Output<OkView>, anyhow::Error> {
        Ok(Output::Render(OkView {}))
    }

    /// The deep leaf, so framework help has something three levels down.
    #[handler]
    pub fn leaf(#[ctx] _ctx: &CommandContext) -> Result<Output<OkView>, anyhow::Error> {
        Ok(Output::Render(OkView {}))
    }
}

/// The clap surface. `nest` and `nest inner` are groups: they require a
/// subcommand, so naming one without a leaf is a usage error.
fn cli() -> Command {
    Command::new("validity")
        .about("Known-edge method coverage for standout")
        .subcommand_required(true)
        .subcommand(
            Command::new("show")
                .about("Render an application template by its registry name")
                .arg(
                    Arg::new("name")
                        .value_name("NAME")
                        .required(true)
                        .help("Template registry name to render"),
                ),
        )
        .subcommand(Command::new("early").about("Registered before templates are loaded"))
        .subcommand(Command::new("late").about("Registered after templates are loaded"))
        .subcommand(
            Command::new("nest")
                .about("Group with a deep leaf beneath it")
                .subcommand_required(true)
                .subcommand(
                    Command::new("inner")
                        .about("Group one level down")
                        .subcommand_required(true)
                        .subcommand(
                            Command::new("leaf").about("The deep leaf, three levels down"),
                        ),
                ),
        )
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        // Registration order, part one: before templates are loaded.
        .command_with("early", handlers::early_Handler, |cfg| {
            cfg.template_name("ok")
        })?
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("app")
        // Registration order, part two: after templates are loaded.
        .command_with("late", handlers::late_Handler, |cfg| cfg.template_name("ok"))?
        .command_with("show", handlers::show_Handler, |cfg| {
            cfg.template_name("show")
        })?
        .command_with("nest.inner.leaf", handlers::leaf_Handler, |cfg| {
            cfg.template_name("ok")
        })?
        .version(env!("CARGO_PKG_VERSION"))
        .build()?;

    let command = cli();
    app.verify_command(&command)?;
    app.run(command, std::env::args());
    Ok(())
}

